'use strict';
const labels={story:'人生失物認領處 ／ 主線故事',coins:'散紙追蹤 ／ 三線跑酷',shipping:'優惠氣流 ／ 升降飛行',instalments:'預算守護花園 ／ 植物防守',pause:'冰火同行 ／ 雙角色合作',plan:'我的七日行動'};
const $=id=>document.getElementById(id);let active=null,originFocus=null;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
function launch(kind){if(!labels[kind])return;originFocus=document.activeElement;const progress=read('life-lost-found-guided-v5',{});if(kind==='plan'&&!progress.budgetDone){showInfo('<div class="eyebrow">故事之後 ／ 七日行動</div><h2>先陪阿俊行到聽朝。</h2><p>完成主線嘅現金流安排，就可以寫自己嘅七日行動。已有進度會保留喺呢個瀏覽器。</p><button class="primary" id="continue-story">繼續主線故事 ↗</button>');$('continue-story').onclick=()=>{$('info-dialog').close();launch('story')};return}active=kind;$('landing').hidden=true;$('play-panel').hidden=false;document.querySelector('footer').hidden=true;$('player-title').textContent=labels[kind];const frame=document.createElement('iframe');frame.title=labels[kind];frame.id='game-frame';frame.allow='autoplay; fullscreen';frame.src='story/index.html'+(kind==='story'?'':kind==='plan'?'?plan=1':'?arcade='+encodeURIComponent(kind));$('frame-host').replaceChildren(frame);history.replaceState(null,'','#play-'+kind);window.scrollTo({top:0,behavior:'instant'})}
function home(){const f=$('game-frame');if(f)f.remove();active=null;$('play-panel').hidden=true;$('landing').hidden=false;document.querySelector('footer').hidden=false;history.replaceState(null,'','#arcade');document.getElementById('arcade').scrollIntoView();if(originFocus?.isConnected)originFocus.focus({preventScroll:true})}
document.querySelectorAll('[data-play]').forEach(b=>b.addEventListener('click',()=>launch(b.dataset.play)));$('back-home').onclick=home;$('player-reload').onclick=()=>{const f=$('game-frame');if(f)f.src=f.src};
document.querySelectorAll('.site-header a[href^="#"]').forEach(a=>a.addEventListener('click',()=>{if(active){$('game-frame')?.remove();active=null;$('play-panel').hidden=true;$('landing').hidden=false;document.querySelector('footer').hidden=false}}));
function showInfo(html){$('info-body').innerHTML=html;$('info-dialog').showModal()};$('info-close').onclick=()=>$('info-dialog').close();
document.querySelector('[data-progress]').onclick=()=>{const s=read('life-lost-found-guided-v5',{}),free=read('website-v1-arcade',{});const clueCount=Array.isArray(s.clues)?s.clues.length:0;const days=Array.isArray(s.stamps)?s.stamps.filter(Boolean).length:0;showInfo(`<div class="eyebrow">只存喺呢個瀏覽器</div><h2>你嘅旅程，留喺度。</h2><div class="progress-row">主線故事 <span class="progress-value">${s.started?'第 '+Math.min(4,Math.max(1,Number(s.stage)||1))+' 幕':'未開始'}</span></div><div class="progress-row">失物線索 <span class="progress-value">${clueCount} / 4</span></div><div class="progress-row">獨立小遊戲 <span class="progress-value">${Object.keys(free).length} / 4</span></div><div class="progress-row">七日行動 <span class="progress-value">${days} / 7 日${s.stamps?.some(x=>x?.demo)?'（含示範）':''}</span></div><p>換裝置或清除瀏覽器資料，進度唔會跟住轉移。故事內可以下載文字行動卡。</p><button class="primary" id="resume-progress">繼續主線故事 ↗</button>`);$('resume-progress').onclick=()=>{$('info-dialog').close();launch('story')}};
$('privacy-open').onclick=()=>showInfo('<div class="eyebrow">私隱說明</div><h2>你嘅記錄，喺你手上。</h2><p>主線進度、遊戲回顧同七日行動存在瀏覽器 localStorage。本網站毋須登入，亦冇加入問卷、帳戶或遙測資料收集。</p><p>請勿喺行動卡填寫戶口、收入或欠款等敏感資料。下載嘅行動卡會保存在你裝置。清除網站資料會移除本機進度。</p><p>外部官方連結按其服務條款及私隱政策運作。網站託管服務本身亦可能處理基本連線記錄。</p>');
window.addEventListener('message',e=>{const f=$('game-frame');if(e.source!==f?.contentWindow||e.origin!==location.origin)return;if(e.data?.type==='website-v1-back')home()});
const start=location.hash.replace('#play-','');if(location.hash.startsWith('#play-')&&labels[start])launch(start);
